    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual zero-divisor supports, uniform binomial bounds and the complete native three-prime independence-polynomial result.",
        H("Rather's three-prime graph"),
        Blocks(
            Paragraph(Text("In every displayed formula, a map marked by the equivalence symbol between rings is a ring equivalence, preserving addition, multiplication, zero and one. All finite cardinalities, ranks and subtraction in binomial indices are natural numbers. B(n,k) denotes the natural binomial coefficient, zero for k greater than n. Every occurrence of H and every quotient in the binomial-curvature formulas is interpreted in the rationals: H(N,m,k)=B(m,k-1) B(N-m,2)/(B(N,k+1) B(k+1,2)). C(G,V) denotes the native finite family of all independent subsets of V, and P(G,V) its integer independence polynomial. The functions int and rat are the canonical casts. Iic and Ici are intervals in all natural indices, so weak monotonicity includes ties and the zero tail.")),

            Paragraph(Text("The three-prime support structure and four-family counting argument are due to Bilal Ahmad Rather, Combinatorial and analytic aspects of independence polynomials of zero divisor graphs, arXiv:2606.04789v1, Theorem 4.1, printed pages 18-20 (https://arxiv.org/abs/2606.04789v1, CC BY 4.0). The graph definitions are on pages 1-2. Problem 1 on page 24 asks for log concavity and unimodality; the underlying graph and subset classification enter the coefficient proof below. The Lean proofs are independently authored.")),

            Definition("Vertex", "Actual ring vertices",
                "For a commutative ring R, a vertex is an element x of R with x nonzero and a witness y in R such that y is nonzero and xy is zero. The zero element is excluded.",
